insert into tarot_cards (id, name, slug, arcana, suit, card_number, rank, image_url, keywords, upright, reversed, yes_no)
values
  ('major_00', 'The Fool', 'the-fool', 'major', null, 0, null, '/assets/images/tarot/major/the-fool.webp', '["Awal Baru","Kepolosan","Petualangan","Spontanitas"]'::jsonb, '{"general":"Sebuah lembaran baru terbuka. Ada dorongan untuk melangkah tanpa terlalu banyak rencana, dipandu oleh rasa percaya pada proses.","love":"Fase baru yang ringan dan spontan; potensi hubungan baru atau babak baru dalam hubungan yang ada.","career":"Peluang atau langkah karier baru yang berani, meski belum semua detail jelas.","spiritual":"Ajakan untuk mempercayai perjalanan tanpa perlu tahu tujuannya lebih dulu.","advice":"Ambil langkah pertama itu. Ketidaktahuan bukan alasan untuk diam."}'::jsonb, '{"general":"Kecerobohan atau keraguan yang membuat langkah tertunda; energi awal yang terasa berisiko tanpa arah.","love":"Keputusan terburu-buru dalam hubungan, atau justru rasa takut mengambil langkah apa pun.","career":"Kurangnya persiapan sebelum melompat ke peluang baru; perlu mengevaluasi ulang rencana.","spiritual":"Terjebak antara ingin bebas dan takut kehilangan pijakan.","advice":"Jeda sebentar untuk menimbang risiko sebelum melangkah lebih jauh."}'::jsonb, 'yes'),
  ('major_01', 'The Magician', 'the-magician', 'major', null, 1, null, '/assets/images/tarot/major/the-magician.webp', '["Kemauan","Manifestasi","Sumber Daya","Kepiawaian"]'::jsonb, '{"general":"Semua alat yang dibutuhkan sudah ada di tangan; saatnya mengubah niat menjadi tindakan nyata.","love":"Kemampuan berkomunikasi dengan jelas dan menciptakan hubungan yang diinginkan secara sadar.","career":"Momentum kuat untuk memulai proyek atau menunjukkan keahlian secara nyata.","spiritual":"Kesadaran bahwa pikiran dan kehendak punya kekuatan untuk membentuk realitas.","advice":"Fokuskan energi pada satu tujuan dan mulai bertindak sekarang."}'::jsonb, '{"general":"Potensi yang belum tergarap, atau kemampuan yang disalahgunakan untuk memanipulasi situasi.","love":"Ketidakjujuran atau kata-kata manis yang tidak sejalan dengan tindakan.","career":"Rencana yang bagus di atas kertas tapi belum dieksekusi, atau taktik yang licik.","spiritual":"Kehendak yang terpecah, sulit fokus pada satu niat.","advice":"Periksa kembali niat sebenarnya sebelum bertindak."}'::jsonb, 'yes'),
  ('major_02', 'The High Priestess', 'the-high-priestess', 'major', null, 2, null, '/assets/images/tarot/major/the-high-priestess.webp', '["Intuisi","Misteri","Alam Bawah Sadar","Kebijaksanaan Batin"]'::jsonb, '{"general":"Jawaban tidak datang dari logika, melainkan dari kepekaan batin yang tenang.","love":"Ada hal yang belum terucap; dengarkan apa yang tersirat, bukan hanya yang tersurat.","career":"Simpan rencana penting untuk sementara; belum saatnya semua dibuka ke publik.","spiritual":"Pintu menuju kebijaksanaan dalam terbuka lebar bila ruang hening diberi tempat.","advice":"Percayai firasat, meski belum bisa menjelaskannya secara logis."}'::jsonb, '{"general":"Sinyal intuitif diabaikan, atau informasi penting sengaja disembunyikan.","love":"Kurangnya keterbukaan emosional; ada jarak yang belum dijembatani.","career":"Rahasia atau informasi yang bocor sebelum waktunya.","spiritual":"Terputus dari suara batin karena terlalu sibuk dengan hal eksternal.","advice":"Luangkan waktu sendiri untuk kembali mendengar diri sendiri."}'::jsonb, 'maybe'),
  ('major_03', 'The Empress', 'the-empress', 'major', null, 3, null, '/assets/images/tarot/major/the-empress.webp', '["Kesuburan","Kelimpahan","Alam","Pengasuhan"]'::jsonb, '{"general":"Musim pertumbuhan dan kelimpahan; sesuatu yang ditanam mulai berbuah dengan sendirinya.","love":"Kehangatan, kenyamanan, dan rasa dirawat dalam hubungan.","career":"Hasil kerja mulai terlihat; ini waktu yang subur untuk berkembang.","spiritual":"Keterhubungan dengan siklus alam dan penerimaan terhadap diri sendiri.","advice":"Beri ruang untuk sesuatu tumbuh dengan wajar, tanpa dipaksa."}'::jsonb, '{"general":"Stagnasi atau kelebihan yang membuat lelah; energi mengasuh yang terkuras habis.","love":"Ketergantungan berlebihan atau kurangnya perhatian pada diri sendiri dalam hubungan.","career":"Proyek yang mandek karena kurang perawatan, atau kelelahan akibat terlalu banyak memberi.","spiritual":"Terputus dari alam dan tubuh sendiri.","advice":"Isi ulang energi sebelum kembali memberi kepada orang lain."}'::jsonb, 'yes'),
  ('major_04', 'The Emperor', 'the-emperor', 'major', null, 4, null, '/assets/images/tarot/major/the-emperor.webp', '["Struktur","Otoritas","Stabilitas","Kepemimpinan"]'::jsonb, '{"general":"Struktur dan disiplin menciptakan fondasi yang kokoh untuk melangkah lebih jauh.","love":"Komitmen yang jelas dan rasa aman dalam hubungan yang stabil.","career":"Kepemimpinan yang tegas membawa hasil; aturan dan rencana jelas sangat membantu.","spiritual":"Menemukan kekuatan lewat keteraturan, bukan lewat kekacauan.","advice":"Tetapkan batas yang jelas dan pegang teguh rencana yang sudah dibuat."}'::jsonb, '{"general":"Kontrol berlebihan atau kekakuan yang justru menghambat pertumbuhan.","love":"Dominasi salah satu pihak, atau kebutuhan akan kontrol yang membuat sesak.","career":"Kepemimpinan otoriter, atau sebaliknya, kurangnya struktur yang menyebabkan kekacauan.","spiritual":"Terlalu terikat pada aturan hingga kehilangan fleksibilitas batin.","advice":"Longgarkan sedikit kendali; tidak semua hal perlu diatur ketat."}'::jsonb, 'yes'),
  ('major_05', 'The Hierophant', 'the-hierophant', 'major', null, 5, null, '/assets/images/tarot/major/the-hierophant.webp', '["Tradisi","Bimbingan","Konformitas","Institusi"]'::jsonb, '{"general":"Nilai, tradisi, atau bimbingan dari figur berpengalaman menjadi pegangan yang berguna.","love":"Hubungan yang dibangun di atas nilai bersama, komitmen formal, atau restu keluarga.","career":"Belajar dari mentor, mengikuti prosedur, atau bekerja dalam sistem yang mapan.","spiritual":"Menemukan makna lewat praktik atau komunitas yang terstruktur.","advice":"Cari nasihat dari yang lebih berpengalaman sebelum menentukan arah sendiri."}'::jsonb, '{"general":"Aturan yang terasa mengekang, atau keinginan untuk keluar dari jalur konvensional.","love":"Menantang norma dalam hubungan, atau ketidakcocokan nilai dengan pasangan.","career":"Merasa terkurung sistem yang kaku; dorongan untuk mencari cara sendiri.","spiritual":"Mempertanyakan kembali kepercayaan yang selama ini diikuti tanpa sadar.","advice":"Boleh menyimpang dari tradisi bila itu memang tak lagi selaras dengan diri sendiri."}'::jsonb, 'maybe'),
  ('major_06', 'The Lovers', 'the-lovers', 'major', null, 6, null, '/assets/images/tarot/major/the-lovers.webp', '["Cinta","Harmoni","Pilihan","Keselarasan Nilai"]'::jsonb, '{"general":"Sebuah pilihan penting muncul, dan menyelaraskannya dengan nilai inti akan membawa harmoni.","love":"Koneksi yang dalam, saling memahami, dan keselarasan nilai dengan orang lain.","career":"Kemitraan atau kolaborasi yang saling menguntungkan; pilihan karier yang sesuai passion.","spiritual":"Integrasi antara berbagai sisi diri menjadi satu keutuhan yang selaras.","advice":"Pilih opsi yang paling sejalan dengan nilai, bukan yang paling nyaman sesaat."}'::jsonb, '{"general":"Ketidakselarasan nilai, konflik batin, atau pilihan yang sulit dan menyakitkan.","love":"Ketidakcocokan, komunikasi yang buruk, atau godaan yang mengganggu komitmen.","career":"Kemitraan yang tidak seimbang, atau pilihan karier yang bertentangan dengan nilai pribadi.","spiritual":"Terpecah antara keinginan dan prinsip; sulit menemukan keselarasan.","advice":"Jujur pada diri sendiri tentang apa yang benar-benar diinginkan sebelum memutuskan."}'::jsonb, 'yes'),
  ('major_07', 'The Chariot', 'the-chariot', 'major', null, 7, null, '/assets/images/tarot/major/the-chariot.webp', '["Kemauan Keras","Kendali","Kemenangan","Determinasi"]'::jsonb, '{"general":"Dua kekuatan yang bertentangan berhasil disatukan dan diarahkan menuju satu tujuan.","love":"Mengatasi perbedaan bersama pasangan lewat kemauan dan arah yang sama.","career":"Kemajuan pesat berkat fokus, disiplin, dan kepercayaan diri yang kuat.","spiritual":"Penguasaan diri yang datang dari menyatukan kehendak dan emosi.","advice":"Tetap fokus pada tujuan meski ada tarikan dari arah berbeda."}'::jsonb, '{"general":"Arah yang kacau, atau kemauan keras yang justru membuat situasi lepas kendali.","love":"Perebutan kendali dalam hubungan, atau tujuan yang tidak lagi sejalan.","career":"Proyek yang mandek karena kurang fokus, atau agresivitas yang kontraproduktif.","spiritual":"Kehilangan arah karena terlalu memaksakan kehendak.","advice":"Berhenti sejenak, tentukan ulang arah sebelum melaju lebih cepat."}'::jsonb, 'yes'),
  ('major_08', 'Strength', 'strength', 'major', null, 8, null, '/assets/images/tarot/major/strength.webp', '["Keberanian","Kesabaran","Kasih Sayang","Pengendalian Diri"]'::jsonb, '{"general":"Kekuatan sejati datang dari kelembutan dan kesabaran, bukan paksaan.","love":"Mengelola konflik dengan kasih sayang dan pengertian, bukan dengan dominasi.","career":"Menghadapi tekanan dengan tenang dan gigih membuahkan hasil jangka panjang.","spiritual":"Menjinakkan sisi impulsif diri lewat welas asih pada diri sendiri.","advice":"Hadapi tantangan dengan kesabaran, bukan dengan melawan secara kasar."}'::jsonb, '{"general":"Keraguan diri atau energi yang terkuras karena menahan sesuatu terlalu lama.","love":"Kurangnya kepercayaan diri dalam hubungan, atau pola yang saling melemahkan.","career":"Merasa tidak berdaya menghadapi tekanan, atau memaksakan kontrol berlebihan.","spiritual":"Berjuang mendamaikan sisi diri yang impulsif dengan sisi yang tenang.","advice":"Bangun kembali kepercayaan diri sebelum menghadapi tantangan berikutnya."}'::jsonb, 'yes'),
  ('major_09', 'The Hermit', 'the-hermit', 'major', null, 9, null, '/assets/images/tarot/major/the-hermit.webp', '["Introspeksi","Kesendirian","Pencarian Batin","Bimbingan Dalam"]'::jsonb, '{"general":"Mundur sejenak dari keramaian untuk mencari jawaban lewat refleksi mendalam.","love":"Butuh ruang sendiri untuk memahami perasaan sebelum melangkah dalam hubungan.","career":"Waktu untuk mengevaluasi arah karier secara mandiri, jauh dari tekanan luar.","spiritual":"Perjalanan batin yang dalam menuju kebijaksanaan pribadi.","advice":"Beri diri waktu sendiri sebelum mengambil keputusan besar."}'::jsonb, '{"general":"Isolasi berlebihan yang berujung kesepian, atau enggan mencari bantuan saat dibutuhkan.","love":"Menarik diri terlalu jauh dari pasangan hingga menciptakan jarak.","career":"Terlalu lama menunda keputusan karena terus-menerus merenung tanpa bertindak.","spiritual":"Kehilangan arah karena introspeksi yang berubah jadi keraguan berlarut.","advice":"Saatnya keluar dari kesendirian dan berbagi apa yang sudah direnungkan."}'::jsonb, 'maybe'),
  ('major_10', 'Wheel of Fortune', 'wheel-of-fortune', 'major', null, 10, null, '/assets/images/tarot/major/wheel-of-fortune.webp', '["Siklus","Takdir","Titik Balik","Peluang"]'::jsonb, '{"general":"Roda kehidupan berputar; sebuah titik balik membawa perubahan yang sudah lama dinanti.","love":"Momen tak terduga yang mengubah arah hubungan menjadi lebih baik.","career":"Peluang baru datang lewat momentum yang sedang berpihak.","spiritual":"Menerima bahwa hidup bergerak dalam siklus yang lebih besar dari kendali pribadi.","advice":"Manfaatkan momentum ini selagi ada; jangan biarkan berlalu begitu saja."}'::jsonb, '{"general":"Perubahan yang terasa di luar kendali, atau siklus buruk yang berulang.","love":"Rasa tidak stabil, seperti keadaan yang naik-turun tanpa arah jelas.","career":"Nasib yang terasa kurang berpihak; perlu bersabar menunggu putaran berikutnya.","spiritual":"Kesulitan menerima bahwa tidak semua hal bisa dikendalikan.","advice":"Fokus pada apa yang bisa dikendalikan, lepaskan yang tidak bisa."}'::jsonb, 'yes'),
  ('major_11', 'Justice', 'justice', 'major', null, 11, null, '/assets/images/tarot/major/justice.webp', '["Keadilan","Kebenaran","Sebab-Akibat","Kejelasan"]'::jsonb, '{"general":"Setiap tindakan membawa konsekuensinya sendiri; kejelasan dan keadilan mulai terlihat.","love":"Hubungan yang setara, jujur, dan saling menghormati.","career":"Keputusan yang adil, kontrak yang jelas, atau hasil kerja keras yang terbayar setimpal.","spiritual":"Memahami hukum sebab-akibat dan bertanggung jawab atas pilihan sendiri.","advice":"Ambil keputusan berdasarkan fakta, bukan emosi sesaat."}'::jsonb, '{"general":"Ketidakadilan, keputusan yang bias, atau konsekuensi yang belum juga datang.","love":"Ketidakseimbangan dalam memberi dan menerima di dalam hubungan.","career":"Perselisihan yang belum terselesaikan, atau proses yang terasa tidak transparan.","spiritual":"Sulit menerima tanggung jawab atas pilihan masa lalu.","advice":"Hadapi konsekuensi dengan jujur, alih-alih menghindarinya."}'::jsonb, 'maybe'),
  ('major_12', 'The Hanged Man', 'the-hanged-man', 'major', null, 12, null, '/assets/images/tarot/major/the-hanged-man.webp', '["Jeda","Perspektif Baru","Pengorbanan","Penyerahan"]'::jsonb, '{"general":"Menunda tindakan untuk melihat situasi dari sudut pandang yang sama sekali baru.","love":"Merelakan kendali dalam hubungan untuk memahami sudut pandang pasangan.","career":"Situasi tertahan sementara; ini waktu yang tepat untuk berpikir ulang, bukan memaksakan.","spiritual":"Pencerahan datang lewat penyerahan, bukan lewat perjuangan.","advice":"Berhenti memaksa; biarkan situasi menunjukkan jalannya sendiri."}'::jsonb, '{"general":"Menunda-nunda tanpa alasan jelas, atau merasa terjebak dalam situasi yang stagnan.","love":"Pengorbanan yang tidak seimbang, salah satu pihak merasa dirugikan.","career":"Stagnasi berkepanjangan karena enggan mengambil keputusan.","spiritual":"Kesulitan melepaskan kendali meski situasi menuntutnya.","advice":"Sudah waktunya bertindak; jeda yang terlalu lama justru merugikan."}'::jsonb, 'no'),
  ('major_13', 'Death', 'death', 'major', null, 13, null, '/assets/images/tarot/major/death.webp', '["Akhir","Transformasi","Transisi","Pelepasan"]'::jsonb, '{"general":"Satu babak berakhir untuk memberi ruang bagi babak baru yang belum terbayangkan.","love":"Berakhirnya sebuah fase hubungan (bukan selalu putus) yang membuka bentuk baru.","career":"Peran atau proyek lama berakhir, membuka jalan bagi arah yang berbeda.","spiritual":"Transformasi mendalam yang menuntut melepaskan versi diri yang lama.","advice":"Lepaskan apa yang sudah tidak lagi berguna, meski terasa berat."}'::jsonb, '{"general":"Menolak perubahan yang sebenarnya sudah tak terhindarkan, hingga terasa terjebak.","love":"Kesulitan mengakhiri hubungan yang sudah tidak sehat.","career":"Bertahan pada situasi kerja yang sudah tidak lagi relevan.","spiritual":"Ketakutan akan perubahan menghambat pertumbuhan.","advice":"Terima bahwa sesuatu memang perlu berakhir agar yang baru bisa dimulai."}'::jsonb, 'no'),
  ('major_14', 'Temperance', 'temperance', 'major', null, 14, null, '/assets/images/tarot/major/temperance.webp', '["Keseimbangan","Moderasi","Perpaduan","Kesabaran"]'::jsonb, '{"general":"Perpaduan yang selaras antara dua hal yang berbeda menciptakan keseimbangan baru.","love":"Kesabaran dan kompromi yang membawa keharmonisan dalam hubungan.","career":"Pendekatan yang seimbang dan bertahap membuahkan hasil yang stabil.","spiritual":"Menemukan titik tengah antara ekstrem, menuju keselarasan batin.","advice":"Ambil jalan tengah; hindari langkah yang terlalu ekstrem."}'::jsonb, '{"general":"Ketidakseimbangan, berlebihan di satu sisi dan kekurangan di sisi lain.","love":"Kompromi yang timpang, atau ketidaksabaran yang memicu gesekan.","career":"Pendekatan yang terburu-buru atau tidak konsisten menghambat hasil.","spiritual":"Kesulitan menemukan titik tenang di tengah kekacauan.","advice":"Perlambat, cari kembali ritme yang lebih seimbang."}'::jsonb, 'yes'),
  ('major_15', 'The Devil', 'the-devil', 'major', null, 15, null, '/assets/images/tarot/major/the-devil.webp', '["Keterikatan","Godaan","Batasan Diri","Bayang-Bayang"]'::jsonb, '{"general":"Terikat pada pola, kebiasaan, atau situasi yang sebenarnya membatasi kebebasan sendiri.","love":"Hubungan yang posesif, ketergantungan, atau pola yang sulit dilepaskan.","career":"Terjebak dalam pekerjaan yang menguras demi rasa aman semu.","spiritual":"Menghadapi sisi bayangan diri yang selama ini dihindari.","advice":"Kenali pola yang mengikat, lalu mulai lepaskan sedikit demi sedikit."}'::jsonb, '{"general":"Mulai menyadari dan melepaskan diri dari ikatan atau kebiasaan yang membatasi.","love":"Keberanian untuk keluar dari hubungan yang tidak sehat.","career":"Membebaskan diri dari rutinitas atau situasi kerja yang menjebak.","spiritual":"Proses membebaskan diri dari ketakutan dan kebiasaan lama.","advice":"Ambil langkah kecil untuk keluar dari pola yang selama ini menahan."}'::jsonb, 'no'),
  ('major_16', 'The Tower', 'the-tower', 'major', null, 16, null, '/assets/images/tarot/major/the-tower.webp', '["Keruntuhan Mendadak","Pengungkapan","Kekacauan","Kebangkitan"]'::jsonb, '{"general":"Struktur yang rapuh runtuh secara tiba-tiba, mengungkap kebenaran yang selama ini tersembunyi.","love":"Kejutan atau krisis yang mengguncang fondasi hubungan.","career":"Perubahan mendadak seperti kehilangan posisi atau rencana yang berantakan.","spiritual":"Keruntuhan keyakinan lama yang justru membuka jalan menuju kebenaran baru.","advice":"Biarkan yang rapuh runtuh; itu membuka ruang untuk membangun yang lebih kokoh."}'::jsonb, '{"general":"Menghindari krisis yang sebenarnya tak terelakkan, hingga keruntuhan tertunda tapi tetap datang.","love":"Konflik yang dipendam alih-alih dihadapi secara terbuka.","career":"Menunda perubahan besar yang sebenarnya sudah mendesak dilakukan.","spiritual":"Ketakutan menghadapi kebenaran yang mengguncang keyakinan.","advice":"Hadapi kebenaran sekarang, sebelum tekanan makin membesar."}'::jsonb, 'no'),
  ('major_17', 'The Star', 'the-star', 'major', null, 17, null, '/assets/images/tarot/major/the-star.webp', '["Harapan","Pemulihan","Inspirasi","Ketenangan"]'::jsonb, '{"general":"Setelah masa sulit, harapan dan ketenangan mulai kembali menuntun arah.","love":"Rasa percaya dan keintiman yang pulih setelah masa yang berat.","career":"Inspirasi baru mengalir; ini waktu yang baik untuk merancang ulang tujuan.","spiritual":"Terhubung kembali dengan harapan dan kepercayaan pada semesta.","advice":"Percaya pada proses pemulihan; biarkan harapan menuntun langkah."}'::jsonb, '{"general":"Rasa putus asa atau kehilangan arah setelah masa sulit yang belum sepenuhnya pulih.","love":"Kepercayaan yang belum sepenuhnya kembali setelah luka lama.","career":"Kehilangan inspirasi atau motivasi untuk melangkah maju.","spiritual":"Kesulitan menemukan kembali rasa percaya pada diri sendiri.","advice":"Beri waktu untuk pemulihan; harapan akan kembali secara perlahan."}'::jsonb, 'yes'),
  ('major_18', 'The Moon', 'the-moon', 'major', null, 18, null, '/assets/images/tarot/major/the-moon.webp', '["Ilusi","Ketidaksadaran","Kecemasan","Intuisi Kabur"]'::jsonb, '{"general":"Sesuatu terasa belum jelas; bayangan dan kecemasan membuat jalan sulit terlihat.","love":"Kesalahpahaman atau ketidakpastian yang belum terungkap sepenuhnya.","career":"Situasi yang membingungkan, informasi belum lengkap untuk mengambil keputusan.","spiritual":"Perjalanan melalui area gelap dari alam bawah sadar.","advice":"Jangan buru-buru memutuskan saat semuanya masih kabur; tunggu kejelasan."}'::jsonb, '{"general":"Kabut mulai menyingkap, kebenaran yang tersembunyi perlahan terungkap.","love":"Kesalahpahaman mulai terurai setelah komunikasi yang lebih jujur.","career":"Kejelasan mulai muncul setelah periode kebingungan.","spiritual":"Ketakutan yang mulai dipahami dan dilepaskan.","advice":"Teruslah mencari kejelasan; jawaban sudah mulai mendekat."}'::jsonb, 'no'),
  ('major_19', 'The Sun', 'the-sun', 'major', null, 19, null, '/assets/images/tarot/major/the-sun.webp', '["Kegembiraan","Vitalitas","Kejelasan","Keberhasilan"]'::jsonb, '{"general":"Kejelasan, kegembiraan, dan vitalitas menyinari situasi yang sedang berjalan.","love":"Kebahagiaan yang tulus dan hubungan yang terasa ringan serta terbuka.","career":"Keberhasilan yang terlihat jelas, diakui, dan membawa kepuasan.","spiritual":"Rasa syukur dan kegembiraan murni atas keberadaan diri.","advice":"Nikmati momen baik ini sepenuhnya, dan bagikan kegembiraannya."}'::jsonb, '{"general":"Kebahagiaan yang tertunda, atau optimisme berlebihan yang menutupi masalah nyata.","love":"Kurang keterbukaan, atau kebahagiaan yang terasa dipaksakan.","career":"Keberhasilan yang belum sepenuhnya terwujud, atau kepuasan yang semu.","spiritual":"Sulit merasakan kegembiraan meski secara lahiriah semua tampak baik.","advice":"Cari sumber kebahagiaan yang lebih tulus, bukan sekadar tampilan luar."}'::jsonb, 'yes'),
  ('major_20', 'Judgement', 'judgement', 'major', null, 20, null, '/assets/images/tarot/major/judgement.webp', '["Kebangkitan","Panggilan Batin","Evaluasi","Pengampunan"]'::jsonb, '{"general":"Panggilan untuk bangkit, mengevaluasi perjalanan, dan menjawab sesuatu yang lebih besar dari diri sendiri.","love":"Momen kejujuran yang membawa hubungan ke pemahaman yang lebih dalam.","career":"Evaluasi menyeluruh yang membuka jalan menuju panggilan yang lebih sesuai.","spiritual":"Kebangkitan kesadaran dan penerimaan atas perjalanan yang sudah dilalui.","advice":"Dengarkan panggilan batin dan beranilah menjawabnya."}'::jsonb, '{"general":"Keraguan pada diri sendiri, atau enggan mengevaluasi ulang pilihan yang sudah diambil.","love":"Sulit memaafkan diri sendiri atau pasangan atas kesalahan masa lalu.","career":"Menunda evaluasi penting yang sebenarnya sudah waktunya dilakukan.","spiritual":"Merasa terputus dari tujuan atau panggilan hidup yang lebih besar.","advice":"Beri diri ruang untuk memaafkan sebelum melangkah ke fase berikutnya."}'::jsonb, 'yes'),
